1	#!/usr/bin/env node
2	/**
3	 * Plugin: claude-self
4	 *
5	 * Claude 프로세스 정보 조회 및 라이프사이클 제어.
6	 * - inspect: 프로세스 정보 조회
7	 * - kill: SIGTERM으로 종료 (claude-loop.sh에서 --continue로 재시작)
8	 * - clear: SIGUSR1로 종료 (claude-loop.sh에서 새 세션으로 재시작)
9	 */
10	
11	import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
12	import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
13	import fs from 'fs';
14	
15	function log(...args) {
16	  console.error('[claude-self]', ...args);
17	}
18	
19	function findClaudePid() {
20	  let pid = process.ppid;
21	
22	  for (let i = 0; i < 5; i++) {
23	    try {
24	      const cmdline = fs.readFileSync(`/proc/${pid}/cmdline`, 'utf-8');
25	      if (cmdline.includes('claude')) {
26	        return pid;
27	      }
28	      const status = fs.readFileSync(`/proc/${pid}/status`, 'utf-8');
29	      const ppidMatch = status.match(/PPid:\s*(\d+)/);
30	      if (!ppidMatch) break;
31	      pid = parseInt(ppidMatch[1], 10);
32	      if (pid <= 1) break;
33	    } catch {
34	      break;
35	    }
36	  }
37	
38	  return process.ppid;
39	}
40	
41	function readProcInfo(pid) {
42	  const procDir = `/proc/${pid}`;
43	
44	  const cmdlineRaw = fs.readFileSync(`${procDir}/cmdline`);
45	  const argv = [];
46	  let start = 0;
47	  for (let i = 0; i < cmdlineRaw.length; i++) {
48	    if (cmdlineRaw[i] === 0) {
49	      const arg = cmdlineRaw.subarray(start, i).toString('utf-8');
50	      if (arg.length > 0) argv.push(arg);
51	      start = i + 1;
52	    }
53	  }
54	  if (start < cmdlineRaw.length) {
55	    const arg = cmdlineRaw.subarray(start).toString('utf-8');
56	    if (arg.length > 0) argv.push(arg);
57	  }
58	
59	  const cwd = fs.readlinkSync(`${procDir}/cwd`);
60	
61	  let exe;
62	  try {
63	    exe = fs.readlinkSync(`${procDir}/exe`);
64	  } catch {
65	    exe = argv[0];
66	  }
67	
68	  return { pid, argv, cwd, exe };
69	}
70	
71	// ── MCP Server ──
72	
73	const server = new McpServer({
74	  name: 'claude-self',
75	  version: '2.0.0',
76	});
77	
78	server.tool(
79	  'inspect',
80	  'Show the current Claude process info: PID, command line, working directory.',
81	  {},
82	  async () => {
83	    try {
84	      const claudePid = findClaudePid();
85	      const info = readProcInfo(claudePid);
86	
87	      const lines = [
88	        `PID: ${info.pid}`,
89	        `Exe: ${info.exe}`,
90	        `CWD: ${info.cwd}`,
91	        `Argv: ${JSON.stringify(info.argv)}`,
92	      ];
93	
94	      return { content: [{ type: 'text', text: lines.join('\n') }] };
95	    } catch (err) {
96	      return { content: [{ type: 'text', text: `ERROR: ${err.message}` }] };
97	    }
98	  }
99	);
100	
101	server.tool(
102	  'kill',
103	  'Kill the current Claude process. If running under claude-loop.sh, it will auto-restart with --continue.',
104	  {},
105	  async () => {
106	    try {
107	      const claudePid = findClaudePid();
108	      log(`Killing Claude PID ${claudePid}`);
109	
110	      process.kill(claudePid, 'SIGTERM');
111	
112	      return { content: [{ type: 'text', text: `Sent SIGTERM to Claude PID ${claudePid}.` }] };
113	    } catch (err) {
114	      return { content: [{ type: 'text', text: `ERROR: ${err.message}` }] };
115	    }
116	  }
117	);
118	
119	server.tool(
120	  'clear',
121	  'Kill the current Claude process and restart with a fresh session (no --continue). Clears conversation context.',
122	  {},
123	  async () => {
124	    try {
125	      const claudePid = findClaudePid();
126	      log(`Sending SIGUSR1 to Claude PID ${claudePid} for fresh restart`);
127	
128	      process.kill(claudePid, 'SIGUSR1');
129	
130	      return { content: [{ type: 'text', text: `Clearing session. Sent SIGUSR1 to Claude PID ${claudePid}.` }] };
131	    } catch (err) {
132	      return { content: [{ type: 'text', text: `ERROR: ${err.message}` }] };
133	    }
134	  }
135	);
136	
137	async function main() {
138	  const transport = new StdioServerTransport();
139	  await server.connect(transport);
140	  log(`MCP server running (ppid: ${process.ppid})`);
141	}
142	
143	main().catch((err) => {
144	  log('Fatal:', err);
145	  process.exit(1);
146	});
147	
